-- Questões originais de estudo: Deitel e Deitel, Java: como programar, 10ª edição.
-- Tradução brasileira do PDF fornecido: Pearson Education do Brasil, 2017.
-- Contexto dos recursos: Java SE 8. Não são questões oficiais nem exercícios transcritos.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas são do arquivo PDF, não da numeração impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 21: Estruturas de dados genéricas personalizadas — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('8cba6bab-33a9-5510-8ab1-55a2f9c93f18', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'Uma classe autorreferencial pode conter:', '["Somente campos static.","Um campo que referencia outra instância do mesmo tipo.","Uma cópia infinita incorporada obrigatoriamente.","Nenhum construtor.","Apenas int."]'::jsonb, 1, 'Referências permitem ligar nós sem incorporar infinitamente a estrutura.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.2, páginas 715 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f1214c54-73f4-5b64-aedd-4a3bb562d962', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Uma estrutura dinâmica pode crescer em execução por:', '["Recompilação de cada elemento.","Alteração do tipo primitivo int.","Ausência de memória.","Modificação do tamanho de um array já criado.","Criação e ligação de novos nós."]'::jsonb, 4, 'A alocação dinâmica usa objetos e referências conforme a necessidade.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.3, páginas 716–727 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('643fd2e2-3351-5343-8626-0907a33b29f5', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'Um nó de lista simplesmente encadeada contém tipicamente:', '["Somente um índice global.","Dado e referência ao próximo nó.","Um construtor de Thread.","Um arquivo de texto.","Uma árvore completa obrigatória."]'::jsonb, 1, 'As ligações definem a sequência dos nós.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.4, páginas 716–727 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cd6bb62c-5840-5515-a5a5-ef54398ce9aa', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Médio', 'O último nó de uma lista simplesmente encadeada convencional tem próximo:', '["O primeiro obrigatoriamente.","null.","Sempre ele mesmo.","Um novo nó infinito.","Um int negativo."]'::jsonb, 1, 'Listas circulares usam outra convenção, que precisa ser declarada.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.4, páginas 716–727 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ca1d405c-add5-5aa4-aab6-43ca7bb2d588', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Médio', 'Uma lista vazia convencional pode ser representada por:', '["Um nó final obrigatório com dado zero.","Referência inicial null.","Um array de tamanho negativo.","Uma String vazia como nó.","Um Thread parado."]'::jsonb, 1, 'A representação deve ser consistente com as operações da estrutura.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.4, páginas 716–727 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5e76954b-94c4-5337-b428-595eb5a88aa1', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Médio', 'Inserir no início de lista encadeada exige principalmente:', '["Percorrer obrigatoriamente todos os nós.","Apagar o último nó sempre.","Converter a lista em array.","Ligar o novo nó ao antigo início e atualizar o início.","Ordenar todos os elementos."]'::jsonb, 3, 'A atualização adequada preserva a sequência anterior após o novo nó.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.4, páginas 716–727 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9799704d-892e-5cfa-98db-0b0489fd3aa4', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Médio', 'Com referência direta ao início, inserir um nó no início tem custo usual:', '["O(n!).","O(n log n).","O(log n) obrigatório.","O(1).","O(n²)."]'::jsonb, 3, 'A operação básica altera uma quantidade constante de referências.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.4, páginas 716–727 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3e8d8cdb-0998-53da-9eb8-a6915d101bf5', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Difícil', 'Acessar a posição k em lista simplesmente encadeada sem índice auxiliar exige normalmente:', '["Ordenação automática.","Busca binária obrigatória.","Uma chave hash implícita.","Acesso constante garantido como array.","Percorrer ligações até o nó desejado."]'::jsonb, 4, 'Não existe acesso posicional direto como em arrays.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.4, páginas 716–727 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8a59aa05-624e-57f8-bc3c-96828a6e1150', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Médio', 'Manter também referência à cauda pode facilitar:', '["Inserção no final sem percorrer toda a lista.","Acesso constante a qualquer posição.","Remoção de qualquer nó sem conhecê-lo.","Eliminação de todos os nós.","Ordenação automática."]'::jsonb, 0, 'A estrutura precisa atualizar a cauda nas operações que a afetam.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.4, páginas 716–727 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cc823820-267f-5e25-931f-a1b0a30cfddc', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Difícil', 'Ao remover o único nó, qual cuidado é necessário com início e cauda?', '["O início deve apontar para si.","Nenhum campo pode ser alterado.","A lista deve crescer.","A cauda deve apontar para um nó removido sempre.","Ambos devem representar lista vazia conforme a implementação."]'::jsonb, 4, 'Referências inconsistentes podem manter nós indevidos ou corromper operações futuras.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.4, páginas 716–727 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('981e62a3-b2ad-5c27-ace4-95cc0215cc98', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Médio', 'A política de uma pilha é:', '["LIFO.","FIFO.","Aleatória.","Ordenação natural obrigatória.","Menor prioridade primeiro."]'::jsonb, 0, 'O último elemento inserido é o primeiro removido.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.5, páginas 728–730 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('14589c9c-0799-52e9-87c7-90a78621940e', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Médio', 'Após empilhar A, B e C, a primeira remoção devolve:', '["ABC.","A.","B.","C.","null obrigatoriamente."]'::jsonb, 3, 'A remoção ocorre no topo da pilha.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.5, páginas 728–730 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d2a26c55-16b6-58d3-a61b-39fc23200dc3', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Médio', 'Empilhar e desempilhar no início de lista encadeada costuma custar:', '["O(1) por operação básica.","O(n log n).","O(log n) obrigatório.","O(n²).","O(n!)."]'::jsonb, 0, 'O topo pode ser mantido pela referência inicial.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.5, páginas 728–730 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('973a6b78-1bc2-57b3-a627-f0294fcafa2e', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Médio', 'A política de uma fila convencional é:', '["FIFO.","Ordem decrescente sempre.","LIFO.","Hash primeiro.","Última chave primeiro."]'::jsonb, 0, 'O primeiro inserido é o primeiro removido.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.6, páginas 731–732 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('319897de-50b5-5710-b0b3-1319d04a236b', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Médio', 'Após enfileirar A, B e C, a primeira remoção devolve:', '["CBA.","C.","A.","B.","null obrigatoriamente."]'::jsonb, 2, 'A remoção ocorre pela cabeça da fila.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.6, páginas 731–732 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('462d1d98-b96a-58dd-9e78-ba2df9f511fb', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Médio', 'Uma fila ligada com cabeça e cauda pode permitir inserção e remoção básicas em:', '["O(n²).","O(n!).","O(1).","O(n log n).","O(log n) obrigatório."]'::jsonb, 2, 'Inserir na cauda e remover da cabeça usa referências diretas.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.6, páginas 731–732 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('42880d96-b743-5ddd-8463-a5fda892add9', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Médio', 'Uma árvore binária permite, por nó, no máximo:', '["Zero filhos.","Um filho.","Dois filhos.","Três filhos.","Um número ilimitado de filhos."]'::jsonb, 2, 'Dois é o limite estrutural, não a obrigação de preencher ambos.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.7, páginas 733–737 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8b87b1c5-ffc1-58e9-83a1-9e8df415b054', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Médio', 'Em uma árvore de busca binária crescente, valores menores que o nó ficam usualmente:', '["Fora da árvore.","Em qualquer lado sem regra.","Somente na raiz.","Sempre na direita.","Na subárvore esquerda."]'::jsonb, 4, 'A regra de ordenação orienta inserção e busca.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.7, páginas 733–737 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8375f6bb-dca6-5b08-9c55-44c618b7bb48', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Médio', 'Percorrer em ordem uma árvore de busca binária válida produz:', '["Sempre ordem de inserção.","Somente folhas.","Valores em ordem crescente conforme seu critério.","Uma ordem aleatória.","Apenas a raiz."]'::jsonb, 2, 'O percurso visita esquerda, nó e direita.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.7, páginas 733–737 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c9e30701-99e0-5f50-9580-2555af82f56d', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Difícil', 'Uma árvore de busca binária não balanceada pode ter busca de pior caso:', '["O(n log n) mínimo.","O(1) sempre.","O(n!) obrigatório.","O(n).","O(log n) garantido."]'::jsonb, 3, 'Uma árvore degenerada pode se comportar como uma cadeia linear.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 21, seção 21.7, páginas 733–737 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
